import requests
import json
from datetime import datetime

# Get more revisions going back to June 2023
url = "https://en.wikipedia.org/w/api.php"

headers = {
    'User-Agent': 'Mozilla/5.0 (compatible; WikipediaResearch/1.0; +https://example.com/bot)'
}

params = {
    "action": "query",
    "format": "json",
    "prop": "revisions",
    "titles": "August 1",
    "rvlimit": 500,  # Get more revisions
    "rvprop": "timestamp|ids|content",
    "rvdir": "older",
    "rvstart": "2023-07-01T00:00:00Z",  # Start from July 2023
    "rvend": "2023-06-01T00:00:00Z"    # End at June 2023
}

try:
    response = requests.get(url, params=params, headers=headers)
    print("Response status:", response.status_code)

    if response.status_code == 200:
        data = response.json()
        print("Success! Got data.")

        # Extract revisions
        pages = data.get('query', {}).get('pages', {})
        for page_id, page_data in pages.items():
            if 'revisions' in page_data:
                revisions = page_data['revisions']
                print(f"Found {len(revisions)} revisions in June-July 2023 timeframe")

                # Find the first revision from June 2023
                for rev in revisions:
                    timestamp = rev.get('timestamp', '')
                    if '2023-06' in timestamp:
                        print(f"June 2023 revision found: {timestamp}, ID: {rev.get('revid')}")
                        break
                else:
                    print("No June 2023 revisions found in this batch")

    else:
        print("Response text:", response.text[:500])

except Exception as e:
    print("Error:", e)
